-- seed_professions.sql — assign professions to the demo people so the globe
-- shows the full colour range. Run after 0008_professions.sql + seed.sql.

update public.profiles set profession = v.prof
from (values
  ('00000000-0000-4000-8000-000000000001'::uuid,'engineer'),
  ('00000000-0000-4000-8000-000000000002'::uuid,'student'),
  ('00000000-0000-4000-8000-000000000003'::uuid,'doctor'),
  ('00000000-0000-4000-8000-000000000004'::uuid,'worker'),
  ('00000000-0000-4000-8000-000000000005'::uuid,'teacher'),
  ('00000000-0000-4000-8000-000000000006'::uuid,'artist'),
  ('00000000-0000-4000-8000-000000000007'::uuid,'student'),
  ('00000000-0000-4000-8000-000000000008'::uuid,'business'),
  ('00000000-0000-4000-8000-000000000009'::uuid,'nurse'),
  ('00000000-0000-4000-8000-00000000000a'::uuid,'lawyer'),
  ('00000000-0000-4000-8000-00000000000b'::uuid,'driver'),
  ('00000000-0000-4000-8000-00000000000c'::uuid,'chef'),
  ('00000000-0000-4000-8000-00000000000d'::uuid,'student'),
  ('00000000-0000-4000-8000-00000000000e'::uuid,'engineer'),
  ('00000000-0000-4000-8000-00000000000f'::uuid,'teacher'),
  ('00000000-0000-4000-8000-000000000010'::uuid,'worker'),
  ('00000000-0000-4000-8000-000000000011'::uuid,'nurse'),
  ('00000000-0000-4000-8000-000000000012'::uuid,'business'),
  ('00000000-0000-4000-8000-000000000013'::uuid,'doctor'),
